css:
.montoya-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #f5f0eb 0%, #e8e0d8 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.montoya-sim-container .montoya-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(26,58,92,0.25);
    text-align: center;
}

.montoya-sim-container .montoya-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 700;
    margin-bottom: 6px;
}

.montoya-sim-container .montoya-sim-header p {
    font-size: 0.95rem;
    opacity: 0.85;
    margin-bottom: 0;
}

.montoya-sim-container .montoya-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 20px;
    font-weight: 600;
}

.montoya-sim-container .montoya-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-bottom: 25px;
}

.montoya-sim-container .montoya-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 18px 12px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.2s ease;
    border-top: 4px solid #ccc;
}

.montoya-sim-container .montoya-sim-status-card:hover {
    transform: translateY(-3px);
}

.montoya-sim-container .montoya-sim-card-gqi { border-top-color: #2980b9; }
.montoya-sim-container .montoya-sim-card-fcs { border-top-color: #e67e22; }
.montoya-sim-container .montoya-sim-card-bvs { border-top-color: #27ae60; }
.montoya-sim-container .montoya-sim-card-sli { border-top-color: #8e44ad; }
.montoya-sim-container .montoya-sim-card-total { border-top-color: #c0392b; }

.montoya-sim-container .montoya-sim-label {
    color: #595959;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.montoya-sim-container .montoya-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #333;
}

.montoya-sim-container .montoya-sim-briefing {
    background: white;
    border-radius: 12px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #1a3a5c;
}

.montoya-sim-container .montoya-sim-briefing h3 {
    color: #1a3a5c;
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.montoya-sim-container .montoya-sim-briefing #briefingText {
    color: #444;
    line-height: 1.7;
    font-size: 0.95rem;
}

.montoya-sim-container .montoya-sim-decisions {
    background: white;
    border-radius: 12px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.montoya-sim-container .montoya-sim-decisions h3 {
    color: #1a3a5c;
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 15px;
}

.montoya-sim-container .montoya-sim-decisions label {
    font-weight: 600;
    color: #333;
    margin-bottom: 6px;
    display: block;
    font-size: 0.9rem;
}

.montoya-sim-container .montoya-sim-decisions select,
.montoya-sim-container .montoya-sim-decisions textarea {
    width: 100%;
    padding: 10px 12px;
    border: 2px solid #ddd;
    border-radius: 8px;
    font-size: 0.9rem;
    transition: border-color 0.2s;
    background: #fafafa;
}

.montoya-sim-container .montoya-sim-decisions select:focus,
.montoya-sim-container .montoya-sim-decisions textarea:focus {
    border-color: #2980b9;
    outline: none;
}

.montoya-sim-container .montoya-sim-actions {
    text-align: center;
    margin-bottom: 25px;
}

.montoya-sim-container .montoya-sim-actions .btn-primary {
    background: linear-gradient(135deg, #1a3a5c, #2c5f8a);
    border: none;
    padding: 12px 40px;
    font-size: 1.05rem;
    border-radius: 10px;
    font-weight: 600;
    margin-right: 10px;
}

.montoya-sim-container .montoya-sim-actions .btn-primary:hover {
    background: linear-gradient(135deg, #15314d, #245174);
}

.montoya-sim-container .montoya-sim-results {
    background: #eef5fb;
    border-left: 5px solid #2980b9;
    border-radius: 10px;
    padding: 14px 18px;
    margin-bottom: 20px;
    color: #1a3a5c;
    font-size: 0.9rem;
    font-weight: 600;
    line-height: 1.5;
}

.montoya-sim-container .montoya-sim-results:empty {
    display: none;
}

.montoya-sim-container .montoya-sim-chart-row {
    margin-bottom: 25px;
}

.montoya-sim-container .montoya-sim-chart {
    background: white;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    height: 300px;
}

.montoya-sim-container .montoya-sim-history {
    background: white;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

@media (max-width: 768px) {
    .montoya-sim-container .montoya-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .montoya-sim-container .montoya-sim-status-card:last-child {
        grid-column: span 2;
    }
}
/* v1.2.0 (EQIL 2026-10-28): carried consequences, non-scored note, debrief, focus and motion */
.montoya-sim-container .montoya-sim-carry {
    margin: 8px 0 0;
    padding: 8px 12px;
    border-left: 4px solid #b45309;
    background: #fff7ed;
    color: #7c2d12;
    border-radius: 6px;
}
.montoya-sim-container .montoya-sim-note {
    font-weight: normal;
    font-size: 0.9em;
    color: #4b5563;
}
.montoya-sim-container select:focus-visible,
.montoya-sim-container textarea:focus-visible,
.montoya-sim-container button:focus-visible {
    outline: 3px solid #1d4ed8;
    outline-offset: 2px;
}
.montoya-cm { text-align: left; color: #1f2937; }
.montoya-cm .montoya-cm-score { margin: 0 0 12px; }
.montoya-cm .montoya-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 8px; margin-bottom: 12px; }
.montoya-cm .montoya-cm-kpi { background: #f3f4f6; border-radius: 8px; padding: 8px 10px; display: flex; flex-direction: column; }
.montoya-cm .montoya-cm-kpi span { font-size: 0.85em; color: #374151; }
.montoya-cm h4 { margin: 14px 0 6px; font-size: 1.05em; }
.montoya-cm blockquote { margin: 0; padding: 8px 12px; border-left: 4px solid #6b7280; background: #f9fafb; color: #1f2937; }
@media (prefers-reduced-motion: reduce) {
    .montoya-sim-container *, .montoya-cm * { transition: none !important; animation: none !important; }
}

