        }
    }

    /* 9. Randomness kept in state. Seeded per sim and per game (per page load where there is no game id),
       so a new session still gets new draws; the generator's position is stored in domainState after every
       call, and an undo restores the domainState it had, so the same round replays the same draws. */
    var pageSeed = Math.floor(Math.random() * 4294967296), seedBase = null;
    function seeded(state, tag, fn) {
        var ds = state && state.domainState, s0;
        // the base is fixed on first use for the life of the page: the boot-time initialise can run before
        // the game id is known, and an undo of round 1 must start from the same place as the first play did
        if (seedBase === null) { seedBase = state && state.gameId ? String(state.gameId) : String(pageSeed); }
