        initialize(state) {
            var _fresh = !state.history || state.history.length === 0;
            if (_fresh || !state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    gqi: 5,
                    fcs: 12,
                    bvs: 9,
                    sli: 5,
                    gqiHistory: [],
                    fcsHistory: [],
                    bvsHistory: [],
                    sliHistory: [],
                    totalHistory: []
                };
            }
            if (_fresh || !state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decisionA: 'A',
                    decisionB: 'A',
                    legacyText: ''
                };
            }
            this._updateBriefing(state);
            this._bindLanguage();
        }

        // v1.2.0: repaint everything the adapter wrote when the language changes, keeping the player's picks
        _bindLanguage() {
            if (this._langBound) { return; }
            this._langBound = true;
            var self = this;
            var repaint = function () {
                try {
                    var f = window.mySimulation;
                    if (!f || !f.state) { return; }
                    var keep = {};
                    ['A', 'B'].forEach(function (x) {
                        var el = document.getElementById('decision' + (f.state.currentPeriod || 1) + x);
                        if (el) { keep[x] = el.value; }
                    });
                    var ta = document.getElementById('legacyTextarea');
                    var text = ta ? ta.value : null;
                    if ((f.state.currentPeriod || 1) <= (f.state.maxPeriods || 5)) { self._updateBriefing(f.state); }
                    ['A', 'B'].forEach(function (x) {
                        var el = document.getElementById('decision' + (f.state.currentPeriod || 1) + x);
                        if (el && keep[x]) { el.value = keep[x]; }
                    });
                    var ta2 = document.getElementById('legacyTextarea');
                    if (ta2 && text !== null) { ta2.value = text; }
                    var lf = self._lastFeedback;
                    if (lf) { self._renderRoundFeedback(lf.round, lf.d[0], lf.d[1], lf.d[2], lf.d[3], lf.total, lf.legacy, lf.fired); }
                } catch (e) { /* a repaint must never break the page */ }
            };
            document.addEventListener('express:langchanged', function () { setTimeout(repaint, 0); });
            try {
                var bus = window.mySimulation && window.mySimulation.eventBus;
                if (bus && typeof bus.on === 'function') { bus.on('language:changed', function () { setTimeout(repaint, 0); }); }
            } catch (e) { /* no event bus in this runtime */ }
        }

        validateDecisions(decisions) {

            // v1.2.0: no check of the submit button here. The framework disables nextPeriodBtn before it calls
            // validateDecisions and owns the re-entry guard, so that check refused every submission (blocked at round 1).
            var round = (window.mySimulation.state.currentPeriod || 1);
            // v1.2.0: one id per decision (decision1A ... decision5A), so each decision is its own control
            var selA = document.getElementById('decision' + round + 'A');
            if (selA) decisions.decisionA = selA.value;

            if (round === 5) {
                var ta = document.getElementById('legacyTextarea');
                if (ta) decisions.legacyText = ta.value;
                decisions.decisionB = 'N';
            } else {
                var selB = document.getElementById('decision' + round + 'B');
                if (selB) decisions.decisionB = selB.value;
            }

            if (!decisions.decisionA) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(round === 5 ? 'select_warning_one' : 'select_warning'), 'warning'
                );
                return false;
            }

            if (round !== 5 && !decisions.decisionB) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var dA = state.decisions.decisionA;
            var dB = state.decisions.decisionB;

            var keyA = 'r' + round + 'a';
            var keyB = 'r' + round + 'b';

            var deltaA = this.SCORING[keyA] ? (this.SCORING[keyA][dA] || {gqi:0,fcs:0,bvs:0,sli:0}) : {gqi:0,fcs:0,bvs:0,sli:0};
            var deltaB = this.SCORING[keyB] ? (this.SCORING[keyB][dB] || {gqi:0,fcs:0,bvs:0,sli:0}) : {gqi:0,fcs:0,bvs:0,sli:0};

            var dGqi = deltaA.gqi + deltaB.gqi;
            var dFcs = deltaA.fcs + deltaB.fcs;
            var dBvs = deltaA.bvs + deltaB.bvs;
            var dSli = deltaA.sli + deltaB.sli;

            // v1.2.0: keep the choices, then apply the consequences of earlier rounds that land now
            var ds0 = state.domainState;
            ds0.picks = Object.assign({}, ds0.picks || {});
            ds0.picks[keyA] = dA;
            if (this.SCORING[keyB]) { ds0.picks[keyB] = dB; }
            var fired = [];
            for (var ci = 0; ci < this.CARRY.length; ci++) {
                var rule = this.CARRY[ci];
                if (rule.round === round && rule.when(ds0.picks)) {
                    dGqi += rule.d.gqi; dFcs += rule.d.fcs; dBvs += rule.d.bvs; dSli += rule.d.sli;
                    fired.push(rule.id);
                }
            }
            ds0.carryLog = (ds0.carryLog || []).concat(fired.map(function (id) { return { round: round, id: id }; }));

            state.domainState.gqi = this._clamp(state.domainState.gqi + dGqi, 0, 25);
            state.domainState.fcs = this._clamp(state.domainState.fcs + dFcs, 0, 25);
            state.domainState.bvs = this._clamp(state.domainState.bvs + dBvs, 0, 25);
            state.domainState.sli = this._clamp(state.domainState.sli + dSli, 0, 25);

            var total = state.domainState.gqi + state.domainState.fcs + state.domainState.bvs + state.domainState.sli;

            state.domainState.gqiHistory.push(state.domainState.gqi);
            state.domainState.fcsHistory.push(state.domainState.fcs);
            state.domainState.bvsHistory.push(state.domainState.bvs);
            state.domainState.sliHistory.push(state.domainState.sli);
            state.domainState.totalHistory.push(total);

            // v1.2.0: re-entrancy is owned by the framework (_submitting guard, buttons disabled during the request).

            this._renderRoundFeedback(round, dGqi, dFcs, dBvs, dSli, total, state.decisions.legacyText || '', fired);

            // platform score: total is already the 0-100 sum of the four dimensions getPerformanceSummary reports as the final verdict, so reuse it directly, clamped
            var overallScore = Math.max(0, Math.min(100, Math.round(total)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            var nextPeriod = round + 1;
            if (nextPeriod <= (state.maxPeriods || 5)) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPeriod });
                }, 500);
            }

            return {
                period: round,
                decisionA: dA,
                decisionB: dB,
                deltaGqi: dGqi,
                deltaFcs: dFcs,
                deltaBvs: dBvs,
                deltaSli: dSli,
                gqi: state.domainState.gqi,
                fcs: state.domainState.fcs,
                bvs: state.domainState.bvs,
                sli: state.domainState.sli,
                total: total,
                carried: fired,
                legacyText: state.decisions.legacyText || ''
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('gqiDisplay', 'domainState.gqi', function(v) { return Math.round(v) + ' / 25'; });
            uiManager.bind('fcsDisplay', 'domainState.fcs', function(v) { return Math.round(v) + ' / 25'; });
            uiManager.bind('bvsDisplay', 'domainState.bvs', function(v) { return Math.round(v) + ' / 25'; });
            uiManager.bind('sliDisplay', 'domainState.sli', function(v) { return Math.round(v) + ' / 25'; });
            uiManager.bind('totalDisplay', 'domainState.gqi', function(v) {
                var s = window.mySimulation.state.domainState;
                var t = Math.round(s.gqi + s.fcs + s.bvs + s.sli);
                return t + ' / 100';
            });
        }

