            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.gqiHistory },
                        { data: state.domainState.fcsHistory },
                        { data: state.domainState.bvsHistory },
                        { data: state.domainState.sliHistory }
                    ]
                }
            };
        }

        _tier(total) {
            if (total >= 85) { return 'excellent'; }
            if (total >= 70) { return 'good'; }
            if (total >= 55) { return 'adequate'; }
            return 'at_risk';
        }

        // v1.2.0: the mistakes of the teaching note, read from the choices actually made (EQIL §6.4, B12)
        _mistakes(p) {
            var out = [];
            if (p.r1a === 'D') { out.push('defer'); }
            if (p.r2a === 'B') { out.push('felipe'); }
            if (p.r2a === 'C' && (p.r3a === 'C' || p.r3a === 'D')) { out.push('no_board'); }
            if (p.r3b === 'A') { out.push('open_door'); }
            if (p.r4b === 'C') { out.push('fait_accompli'); }
            return out;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var t = function (k) { return window.mySimulation.t(k); };
            var last = history[history.length - 1];
            var r = last.results || {};
            var total = (r.gqi || 0) + (r.fcs || 0) + (r.bvs || 0) + (r.sli || 0);
            var ds = (window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var picks = ds.picks || {};
            var tier = this._tier(total);

            // turning point: the round whose combined change was lowest
            var worst = null;
            for (var h = 0; h < history.length; h++) {
                var x = history[h].results || {};
                var sum = (x.deltaGqi || 0) + (x.deltaFcs || 0) + (x.deltaBvs || 0) + (x.deltaSli || 0);
                if (worst === null || sum < worst.sum) { worst = { round: x.period || (h + 1), sum: sum }; }
            }
            var mk = this._mistakes(picks);
            var insights = [];
            mk.forEach(function (m) { insights.push(t('mk_' + m)); });
            if (r.gqi < 12) insights.push(t('ins_gqi_low'));
            if (r.fcs < 12) insights.push(t('ins_fcs_low'));
            if (r.bvs < 12) insights.push(t('ins_bvs_low'));
            if (r.sli < 12) insights.push(t('ins_sli_low'));
            if (!mk.length) insights.push(t('ins_no_mistake'));
            if (insights.length < 3) insights.push(t('ins_procedure'));

            return {
                totalScore: total,
                overallScore: total,
                score: total,
                composite: total,
                gqi: r.gqi,
                fcs: r.fcs,
                bvs: r.bvs,
                sli: r.sli,
                performance: tier,
                performanceKey: tier,
                performanceLabel: t('tier_' + tier),
                mistakes: mk,
                turningRound: worst ? worst.round : null,
                turningDelta: worst ? worst.sum : null,
                legacyText: (history[history.length - 1].results || {}).legacyText || '',
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function (k) { return window.mySimulation.t(k); };
            var esc = function (v) { return String(v === undefined || v === null ? '' : v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('\x22').join('&quot;'); };
            var kpi = function (k, v) { return '<div class="montoya-cm-kpi"><span>' + esc(t(k)) + '</span><strong>' + esc(v) + ' / 25</strong></div>'; };
            var html = '<div class="montoya-cm" role="region" aria-label="' + esc(t('cm_title')) + '">';
            html += '<h3 class="montoya-cm-score">' + esc(summary.totalScore) + ' / 100 · ' + esc(summary.performanceLabel || '') + '</h3>';
            html += '<div class="montoya-cm-kpis">' + kpi('gqi_label', summary.gqi) + kpi('fcs_label', summary.fcs) + kpi('bvs_label', summary.bvs) + kpi('sli_label', summary.sli) + '</div>';
            if (summary.turningRound) {
                html += '<h4>' + esc(t('cm_turning')) + '</h4><p>' + esc(t('cm_turning_text').replace('{r}', summary.turningRound).replace('{d}', (summary.turningDelta > 0 ? '+' : '') + summary.turningDelta)) + '</p>';
            }
            html += '<h4>' + esc(t('cm_insights')) + '</h4><ul>';
            (summary.insights || []).forEach(function (s) { html += '<li>' + esc(s) + '</li>'; });
            html += '</ul>';
            if (summary.legacyText && String(summary.legacyText).trim()) {
                html += '<h4>' + esc(t('cm_legacy')) + '</h4><blockquote>' + esc(String(summary.legacyText).trim()) + '</blockquote>';
            }
            html += '<h4>' + esc(t('cm_questions')) + '</h4><ol><li>' + esc(t('cm_q1')) + '</li><li>' + esc(t('cm_q2')) + '</li><li>' + esc(t('cm_q3')) + '</li></ol>';
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            var total = results.total || 0;
            var round = results.period || 0;

            if (results.deltaFcs < -2) return window.mySimulation.t('hint_family_tension');
            if (results.deltaGqi < 0) return window.mySimulation.t('hint_weak_governance');
            if (round >= 3 && results.bvs < 8) return window.mySimulation.t('hint_business_risk');
            if (total >= 70 && round >= 4) return window.mySimulation.t('hint_strong_position');
            return null;
        }

