        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 4);
            var round = this._getRoundData(idx);
            var idA = 'decision' + (idx + 1) + 'A', idB = 'decision' + (idx + 1) + 'B';

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;

            var contA = document.getElementById('decisionAContainer');
            if (contA) {
                var htmlA = '<label for="' + idA + '">' + round.labelA + '</label>';
                htmlA += '<select id="' + idA + '" class="form-control">';
                htmlA += '<option value="">' + window.mySimulation.t('select_placeholder') + '</option>';
                for (var i = 0; i < round.optionsA.length; i++) {
                    htmlA += '<option value="' + round.optionsA[i].v + '">' + round.optionsA[i].t + '</option>';
                }
                htmlA += '</select>';
                contA.innerHTML = htmlA;
            }

            var contB = document.getElementById('decisionBContainer');
            if (contB) {
                if (round.typeB === 'textarea') {
                    var htmlB = '<label for="legacyTextarea">' + round.labelB + ' <span class="montoya-sim-note">(' + window.mySimulation.t('legacy_not_scored') + ')</span></label>';
                    htmlB += '<textarea id="legacyTextarea" class="form-control" rows="4" placeholder="' + window.mySimulation.t('legacy_placeholder') + '"></textarea>';
                    contB.innerHTML = htmlB;
                } else {
                    var htmlB2 = '<label for="' + idB + '">' + round.labelB + '</label>';
                    htmlB2 += '<select id="' + idB + '" class="form-control">';
                    htmlB2 += '<option value="">' + window.mySimulation.t('select_placeholder') + '</option>';
                    for (var j = 0; j < round.optionsB.length; j++) {
                        htmlB2 += '<option value="' + round.optionsB[j].v + '">' + round.optionsB[j].t + '</option>';
                    }
                    htmlB2 += '</select>';
                    contB.innerHTML = htmlB2;
                }
            }

        }

        _renderRoundFeedback(round, dGqi, dFcs, dBvs, dSli, total, legacyText, fired) {
            var el = document.getElementById('roundResults');
            if (!el) return;
            var t = function(k) { return window.mySimulation.t(k); };
            var sign = function(n) { return (n > 0 ? '+' : '') + n; };
            var msg = t('period_label') + ' ' + round + ' · '
                + t('gqi_label') + ' ' + sign(dGqi) + ', '
                + t('fcs_label') + ' ' + sign(dFcs) + ', '
                + t('bvs_label') + ' ' + sign(dBvs) + ', '
                + t('sli_label') + ' ' + sign(dSli) + ' · '
                + t('total_label') + ': ' + total + '/100';
            if (round === 5 && legacyText && legacyText.trim()) {
                msg += ' — ' + t('legacy_recorded_label') + ' \u201C' + legacyText.trim() + '\u201D';
            }
            el.textContent = msg;
            (fired || []).forEach(function (id) {
                var p = document.createElement('p');
                p.className = 'montoya-sim-carry';
                p.textContent = t('carry_' + id);
                el.appendChild(p);
            });
            this._lastFeedback = { round: round, d: [dGqi, dFcs, dBvs, dSli], total: total, legacy: legacyText, fired: fired || [] };
        }

        _clamp(v, min, max) {
            return Math.max(min, Math.min(max, v));
        }
